// GenAI: The overall structure of DOMContentLoaded and event listeners was generated by AI to ensure safe DOM manipulation.
document.addEventListener('DOMContentLoaded', () => {
    const faqButtons = document.querySelectorAll('.faq-btn');
    if (faqButtons.length > 0) {
        faqButtons.forEach(button => {
            button.addEventListener('click', () => {
                const parentItem = button.closest('.faq-item');
                const isExpanded = parentItem.classList.contains('active');

                faqButtons.forEach(otherBtn => {
                    if (otherBtn !== button) {
                        const otherItem = otherBtn.closest('.faq-item');
                        if (otherItem) {
                            otherItem.classList.remove('active');
                        }
                    }
                });

                if (isExpanded) {
                    parentItem.classList.remove('active');
                } else {
                    parentItem.classList.add('active');
                }
            });
        });
    }

    const applianceSelect = document.getElementById('appliance-select');
    const powerInput = document.getElementById('power-input');
    const hoursInput = document.getElementById('hours-input');
    const priceInput = document.getElementById('price-input');
    
    if (applianceSelect && powerInput && hoursInput && priceInput) {
        const resDailyCost = document.getElementById('result-daily-cost');
        const resDailyKwh = document.getElementById('result-daily-kwh');
        const resMonthlyCost = document.getElementById('result-monthly-cost');
        const resYearlyCost = document.getElementById('result-yearly-cost');

        const errPower = document.getElementById('power-error');
        const errHours = document.getElementById('hours-error');
        const errPrice = document.getElementById('price-error');

        const formatter = new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
        });

        function calculate() {
            let isValid = true;
            
            const powerVal = parseFloat(powerInput.value);
            if (isNaN(powerVal) || powerVal <= 0) {
                errPower.classList.add('show');
                isValid = false;
            } else {
                errPower.classList.remove('show');
            }

            const hoursVal = parseFloat(hoursInput.value);
            if (isNaN(hoursVal) || hoursVal <= 0 || hoursVal > 24) {
                errHours.classList.add('show');
                isValid = false;
            } else {
                errHours.classList.remove('show');
            }

            const priceVal = parseFloat(priceInput.value);
            if (isNaN(priceVal) || priceVal <= 0) {
                errPrice.classList.add('show');
                isValid = false;
            } else {
                errPrice.classList.remove('show');
            }

            if (!isValid) {
                resDailyCost.textContent = '$0.00';
                resDailyKwh.textContent = '0.00';
                resMonthlyCost.textContent = '$0.00';
                resYearlyCost.textContent = '$0.00';
                return;
            }

            const dailyKwh = (powerVal * hoursVal) / 1000;
            const dailyCost = dailyKwh * priceVal;
            const monthlyCost = dailyCost * 30;
            const yearlyCost = dailyCost * 365;

            resDailyKwh.textContent = dailyKwh.toFixed(2);
            resDailyCost.textContent = formatter.format(dailyCost);
            resMonthlyCost.textContent = formatter.format(monthlyCost);
            resYearlyCost.textContent = formatter.format(yearlyCost);
        }

        applianceSelect.addEventListener('change', (e) => {
            if (e.target.value !== 'custom') {
                powerInput.value = e.target.value;
                calculate();
            } else {
                powerInput.value = '';
                calculate();
            }
        });

        ['input', 'change'].forEach(evt => {
            powerInput.addEventListener(evt, calculate);
            hoursInput.addEventListener(evt, calculate);
            priceInput.addEventListener(evt, calculate);
        });

        applianceSelect.value = "150";
        powerInput.value = "150";
        hoursInput.value = "24";
        calculate();
    }
});
